-- ============================================================================
-- CYBERSOFT DATA & AI LAB - MASTER POSTGRES SANDBOX SEED SCRIPT (ALL 4 DATASETS)
-- Organized into 4 Schema Namespaces to Prevent Table Name Collisions:
--   1. retail.*    (Task 06: customers, employees, products, orders, order_details)
--   2. hr.*        (Task 07: employees, attendance, kpi_evaluations, training_records, turnovers)
--   3. education.* (Task 05: students)
--   4. inventory.* (Task 13: warehouses, products, purchase_orders, movements, dispatches, audits)
-- ============================================================================

-- ============================================================================
-- CYBERSOFT DATA & AI LAB - POSTGRES SANDBOX SEED SCRIPT
-- Dataset: Retail Sales (retail schema) (Variant: CLEAN)
-- ============================================================================

BEGIN;

CREATE SCHEMA IF NOT EXISTS retail;
SET search_path TO retail;

DROP TABLE IF EXISTS retail.order_details CASCADE;
DROP TABLE IF EXISTS retail.orders CASCADE;
DROP TABLE IF EXISTS retail.products CASCADE;
DROP TABLE IF EXISTS retail.employees CASCADE;
DROP TABLE IF EXISTS retail.customers CASCADE;

-- Table: customers (200 rows, SHA-256: 3f1c14f32c4c1f3689b1ad4d27253273e4be5149c3f50bbe45f3512ebd0ecd72)
CREATE TABLE customers (
    customer_id VARCHAR(50) PRIMARY KEY,
    full_name VARCHAR(150),
    email VARCHAR(150),
    phone VARCHAR(25),
    city VARCHAR(150),
    customer_segment VARCHAR(150),
    created_at VARCHAR(150)
);





-- Table: employees (20 rows, SHA-256: 92e42a6e63a0e9ecdda8147af61ca719a831ceb88c4ae2c4926db490fbb9dd8c)
CREATE TABLE employees (
    employee_id VARCHAR(50) PRIMARY KEY,
    full_name VARCHAR(150),
    department VARCHAR(150),
    position VARCHAR(150),
    hire_date DATE,
    region VARCHAR(150)
);


-- Table: products (50 rows, SHA-256: 25b2a7df10714be1678c28c5ae734476faac4f1a8d48173599102b1f88adc729)
CREATE TABLE products (
    product_id VARCHAR(50) PRIMARY KEY,
    product_name VARCHAR(150),
    category VARCHAR(150),
    cost_price NUMERIC(14,2),
    selling_price NUMERIC(14,2),
    stock_quantity INT,
    status VARCHAR(150)
);


-- Table: orders (1000 rows, SHA-256: ac5e353b4ddd40591a1a6fb8d2b16d63ab3a286cec726f15cbe4ff29a1958ef3)
CREATE TABLE orders (
    order_id VARCHAR(50) PRIMARY KEY,
    customer_id VARCHAR(50),
    employee_id VARCHAR(50),
    order_date DATE,
    shipping_date DATE,
    order_status VARCHAR(150),
    payment_method VARCHAR(150),
    total_amount NUMERIC(14,2)
);





















-- Table: order_details (1803 rows, SHA-256: bf07ccd995fd9832980419684aca7546a6b598fe350a06f358c90dc463a7f92c)
CREATE TABLE order_details (
    order_detail_id VARCHAR(50) PRIMARY KEY,
    order_id VARCHAR(50),
    product_id VARCHAR(50),
    quantity INT,
    unit_price NUMERIC(14,2),
    discount NUMERIC(6,2),
    line_total NUMERIC(14,2)
);






































COMMIT;


-- ============================================================================
-- CYBERSOFT DATA & AI LAB - POSTGRES SANDBOX SEED SCRIPT
-- Dataset: HR Operations (hr schema) (Variant: CLEAN)
-- ============================================================================

BEGIN;

CREATE SCHEMA IF NOT EXISTS hr;
SET search_path TO hr;

DROP TABLE IF EXISTS hr.turnovers CASCADE;
DROP TABLE IF EXISTS hr.training_records CASCADE;
DROP TABLE IF EXISTS hr.kpi_evaluations CASCADE;
DROP TABLE IF EXISTS hr.attendance CASCADE;
DROP TABLE IF EXISTS hr.employees CASCADE;

-- Table: employees (250 rows, SHA-256: e62d5d71857fd7f9419a4cad40c8c53635028396d8e6bd06d7be45635a4999ae)
CREATE TABLE employees (
    employee_id VARCHAR(50) PRIMARY KEY,
    full_name VARCHAR(150),
    gender VARCHAR(150),
    birth_date DATE,
    department VARCHAR(150),
    position VARCHAR(150),
    hire_date DATE,
    base_salary NUMERIC(14,2),
    status VARCHAR(150),
    manager_id VARCHAR(50),
    work_location VARCHAR(150)
);






-- Table: attendance (5092 rows, SHA-256: 26b1ba4e4dec35de1c80e05f9ffbe1f834a7b5a3b65d957b19ba4c9adedb1851)
CREATE TABLE attendance (
    attendance_id VARCHAR(50) PRIMARY KEY,
    employee_id VARCHAR(50),
    work_date DATE,
    check_in VARCHAR(150),
    check_out VARCHAR(150),
    hours_worked NUMERIC(6,2),
    overtime_hours NUMERIC(6,2),
    status VARCHAR(150)
);







































































































-- Table: kpi_evaluations (654 rows, SHA-256: b4c93795a3c0b9dc3a51a667488e4a9890403c52efc82a906aeb5de48af0b549)
CREATE TABLE kpi_evaluations (
    kpi_id VARCHAR(50) PRIMARY KEY,
    employee_id VARCHAR(50),
    evaluation_period VARCHAR(150),
    target_score NUMERIC(6,2),
    actual_score NUMERIC(6,2),
    completion_rate VARCHAR(150),
    rating VARCHAR(150),
    reviewer_id VARCHAR(50)
);















-- Table: training_records (450 rows, SHA-256: 9dc7bba1cc7c92c915f7fdfa33c76080516f30447079b1cc99ba0b899f3cefeb)
CREATE TABLE training_records (
    record_id VARCHAR(50) PRIMARY KEY,
    employee_id VARCHAR(50),
    course_name VARCHAR(150),
    training_type VARCHAR(150),
    start_date DATE,
    end_date DATE,
    score NUMERIC(6,2),
    completion_status VARCHAR(150),
    training_cost NUMERIC(14,2)
);










-- Table: turnovers (35 rows, SHA-256: 52faba1bcc297be1e4e48013052647d72b8b54659c3b32eb6868d59e7e6ab96e)
CREATE TABLE turnovers (
    turnover_id VARCHAR(50) PRIMARY KEY,
    employee_id VARCHAR(50),
    resignation_date DATE,
    last_working_date DATE,
    reason VARCHAR(150),
    exit_interview_score NUMERIC(6,2),
    handover_status VARCHAR(150)
);


COMMIT;


-- ============================================================================
-- CYBERSOFT DATA & AI LAB - POSTGRES SANDBOX SEED SCRIPT
-- Dataset: Student Records (education schema) (Variant: CLEAN)
-- ============================================================================

BEGIN;

CREATE SCHEMA IF NOT EXISTS education;
SET search_path TO education;

DROP TABLE IF EXISTS education.students CASCADE;

-- Table: students (10 rows, SHA-256: ac74998f48b26329a55ece542ac12747b127782b3efc0d47944c0897ee50b6eb)
CREATE TABLE students (
    student_id VARCHAR(50) PRIMARY KEY,
    full_name VARCHAR(150),
    email VARCHAR(150),
    age VARCHAR(150),
    track VARCHAR(150),
    course_id VARCHAR(50),
    course_name VARCHAR(150),
    gpa VARCHAR(150),
    tuition_fee VARCHAR(150),
    status VARCHAR(150),
    enrollment_date DATE,
    graduation_date DATE
);


COMMIT;


-- ============================================================================
-- CYBERSOFT DATA & AI LAB - POSTGRES SANDBOX SEED SCRIPT
-- Dataset: Inventory (inventory schema) (Variant: CLEAN)
-- ============================================================================

BEGIN;

CREATE SCHEMA IF NOT EXISTS inventory;
SET search_path TO inventory;

DROP TABLE IF EXISTS inventory.inventory_audits CASCADE;
DROP TABLE IF EXISTS inventory.sales_dispatches CASCADE;
DROP TABLE IF EXISTS inventory.inventory_movements CASCADE;
DROP TABLE IF EXISTS inventory.purchase_orders CASCADE;
DROP TABLE IF EXISTS inventory.products CASCADE;
DROP TABLE IF EXISTS inventory.warehouses CASCADE;

-- Table: warehouses (3 rows, SHA-256: 33092dcde6e1800665dfb8a32469b5f23b961f3e7d40c9a62640344a55029a42)
CREATE TABLE warehouses (
    warehouse_id VARCHAR(50) PRIMARY KEY,
    warehouse_name VARCHAR(150),
    region VARCHAR(150),
    capacity_sqm VARCHAR(150),
    manager_name VARCHAR(150),
    status VARCHAR(150)
);


-- Table: products (50 rows, SHA-256: b2b9dcd69ac0b83cc4050ee8e716a48db2cda55dda8b6912174a431d1378dda9)
CREATE TABLE products (
    product_id VARCHAR(50) PRIMARY KEY,
    sku VARCHAR(150),
    product_name VARCHAR(150),
    category VARCHAR(150),
    category_id VARCHAR(50),
    unit_cost NUMERIC(14,2),
    unit_price NUMERIC(14,2),
    lead_time_days TIME,
    min_safety_stock VARCHAR(150),
    reorder_point VARCHAR(150)
);


-- Table: purchase_orders (89 rows, SHA-256: c8be68fe1045bbfa02e31fb020b2f1f3e7c4cfa48977a2eb2bdcc2da015e85ef)
CREATE TABLE purchase_orders (
    po_id VARCHAR(50) PRIMARY KEY,
    vendor_name VARCHAR(150),
    order_date DATE,
    expected_delivery_date DATE,
    actual_delivery_date DATE,
    status VARCHAR(150),
    total_amount NUMERIC(14,2)
);



-- Table: inventory_movements (2035 rows, SHA-256: 1678d11e32164f2e8bff811d3503a461877446c7e921a14f25d6e58bf92beec6)
CREATE TABLE inventory_movements (
    movement_id VARCHAR(50) PRIMARY KEY,
    timestamp TIME,
    warehouse_id VARCHAR(50),
    product_id VARCHAR(50),
    movement_type VARCHAR(150),
    direction VARCHAR(150),
    quantity INT,
    unit_cost NUMERIC(14,2),
    reference_doc VARCHAR(150),
    notes VARCHAR(150)
);










































-- Table: sales_dispatches (500 rows, SHA-256: 097eba204f2ba49ebb5535f5bf0ebcf66392bcd43efdba6d4113853f3527ccdf)
CREATE TABLE sales_dispatches (
    dispatch_id VARCHAR(50) PRIMARY KEY,
    order_id VARCHAR(50),
    warehouse_id VARCHAR(50),
    dispatch_date DATE,
    delivery_status VARCHAR(150),
    shipping_carrier VARCHAR(150),
    lead_time_hours TIME
);











-- Table: inventory_audits (60 rows, SHA-256: 3e73da196f7acb01de29b112b232d7efedeb95d496061e577d29d7ab02c2d6b8)
CREATE TABLE inventory_audits (
    audit_id VARCHAR(50) PRIMARY KEY,
    audit_date DATE,
    warehouse_id VARCHAR(50),
    product_id VARCHAR(50),
    book_quantity INT,
    physical_quantity INT,
    discrepancy_qty VARCHAR(150),
    reason_code VARCHAR(50)
);



COMMIT;


-- Set search path to access all schemas easily
SET search_path TO retail, hr, education, inventory, public;

-- Post-verification query
SELECT 'retail.customers' AS tbl, count(*) FROM retail.customers
UNION ALL SELECT 'retail.orders', count(*) FROM retail.orders
UNION ALL SELECT 'hr.employees', count(*) FROM hr.employees
UNION ALL SELECT 'hr.attendance', count(*) FROM hr.attendance
UNION ALL SELECT 'education.students', count(*) FROM education.students
UNION ALL SELECT 'inventory.warehouses', count(*) FROM inventory.warehouses;
